import React, { useState, useEffect } from 'react';
import { Lightbulb, RefreshCw } from 'lucide-react';

const wildlifeTips = [
  "Golden hour (first hour after sunrise, last hour before sunset) provides the best lighting for wildlife photography.",
  "Use a fast shutter speed (1/500s or faster) to freeze motion when photographing birds in flight.",
  "For sharp wildlife portraits, focus on the animal's eyes - they should always be tack sharp.",
  "Patience is key in wildlife photography. Spend time observing animal behavior before taking shots.",
  "Use a telephoto lens (200mm+) to maintain safe distance from wildlife while getting close-up shots.",
  "Shoot in burst mode to capture the perfect moment during fast animal movements.",
  "Lower your camera angle to get on the same level as smaller animals for more engaging compositions.",
  "Research your subjects beforehand - knowing animal behavior helps predict great photo opportunities.",
  "Use back-button focus to maintain control over focus points when tracking moving subjects.",
  "Carry extra batteries - cold weather and long shooting sessions drain power quickly.",
  "For bird photography, focus on the bird's head and let the body fall into the depth of field.",
  "Use natural frames like branches or rocks to add depth and context to your wildlife shots.",
  "Shoot in RAW format to have maximum flexibility in post-processing wildlife images.",
  "Be aware of your background - a cluttered background can distract from your subject.",
  "Use continuous autofocus (AI Servo/AF-C) when photographing moving wildlife."
];

const WildlifeTips: React.FC = () => {
  const [currentTip, setCurrentTip] = useState(0);

  useEffect(() => {
    if (wildlifeTips && wildlifeTips.length > 0) {
      setCurrentTip(Math.floor(Math.random() * wildlifeTips.length));
    }
  }, []);

  const getNewTip = () => {
    if (wildlifeTips && wildlifeTips.length > 0) {
      let newTip;
      do {
        newTip = Math.floor(Math.random() * wildlifeTips.length);
      } while (newTip === currentTip && wildlifeTips.length > 1);
      setCurrentTip(newTip);
    }
  };

  return (
    <div className="bg-gradient-to-r from-green-50 to-blue-50 rounded-xl p-6 border border-green-200">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center space-x-2">
          <Lightbulb className="w-6 h-6 text-yellow-600" />
          <h3 className="text-xl font-bold text-green-800">Wildlife Photography Tip</h3>
        </div>
        <button
          onClick={getNewTip}
          className="flex items-center space-x-1 px-3 py-1 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors"
        >
          <RefreshCw className="w-4 h-4" />
          <span className="text-sm">New Tip</span>
        </button>
      </div>
      <p className="text-green-700 leading-relaxed">
        {wildlifeTips && wildlifeTips[currentTip] ? wildlifeTips[currentTip] : "Loading tip..."}
      </p>
      
      <div className="mt-4 text-xs text-green-600">
        Tip {currentTip + 1} of {wildlifeTips ? wildlifeTips.length : 0}
      </div>
    </div>
  );
};

export default WildlifeTips;