import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { CheckCircle, XCircle, AlertTriangle } from 'lucide-react';

interface CaseStudy {
  id: string;
  title: string;
  scenario: string;
  options: {
    id: string;
    text: string;
    correct: boolean;
    explanation: string;
  }[];
  difficulty: 'beginner' | 'intermediate' | 'advanced';
}

const caseStudies: CaseStudy[] = [
  {
    id: 'case1',
    title: 'Lion Pride Sighting',
    scenario: 'You spot a lion pride with cubs resting under a tree. Other vehicles are already present, but you want the perfect shot. What should you do?',
    options: [
      {
        id: 'a',
        text: 'Drive closer and use flash to get a clear photo',
        correct: false,
        explanation: 'Never use flash or get too close to wildlife, especially with cubs present.'
      },
      {
        id: 'b',
        text: 'Wait patiently at a respectful distance with telephoto lens',
        correct: true,
        explanation: 'Correct! Patience and proper equipment are key to ethical wildlife photography.'
      },
      {
        id: 'c',
        text: 'Make noise to get the lions to look at you',
        correct: false,
        explanation: 'Never harass or provoke animals for a photo opportunity.'
      }
    ],
    difficulty: 'beginner'
  },
  {
    id: 'case2',
    title: 'Endangered Rhino Encounter',
    scenario: 'You photograph a rare black rhino. The shot is amazing and you want to share it on social media. What precautions should you take?',
    options: [
      {
        id: 'a',
        text: 'Post immediately with exact location details',
        correct: false,
        explanation: 'Never share location data for endangered species - this helps poachers.'
      },
      {
        id: 'b',
        text: 'Remove all geolocation data before posting',
        correct: true,
        explanation: 'Correct! Always protect endangered animals by removing location information.'
      },
      {
        id: 'c',
        text: 'Wait several months before posting',
        correct: false,
        explanation: 'While cautious, removing metadata is the key protection needed.'
      }
    ],
    difficulty: 'intermediate'
  }
];

export const EthicsInteractiveCases: React.FC = () => {
  const [selectedAnswers, setSelectedAnswers] = useState<Record<string, string>>({});
  const [showResults, setShowResults] = useState<Record<string, boolean>>({});

  const handleAnswerSelect = (caseId: string, optionId: string) => {
    setSelectedAnswers(prev => ({ ...prev, [caseId]: optionId }));
  };

  const handleSubmit = (caseId: string) => {
    setShowResults(prev => ({ ...prev, [caseId]: true }));
  };

  const resetCase = (caseId: string) => {
    setSelectedAnswers(prev => {
      const newAnswers = { ...prev };
      delete newAnswers[caseId];
      return newAnswers;
    });
    setShowResults(prev => ({ ...prev, [caseId]: false }));
  };

  return (
    <div className="space-y-6">
      <div className="text-center mb-8">
        <h2 className="text-2xl font-bold mb-2">Interactive Case Studies</h2>
        <p className="text-gray-600">Test your understanding with real-world scenarios</p>
      </div>

      {caseStudies.map((caseStudy) => {
        const selectedAnswer = selectedAnswers[caseStudy.id];
        const showResult = showResults[caseStudy.id];
        const selectedOption = caseStudy.options.find(opt => opt.id === selectedAnswer);

        return (
          <Card key={caseStudy.id} className="w-full">
            <CardHeader>
              <div className="flex justify-between items-start">
                <CardTitle className="text-lg">{caseStudy.title}</CardTitle>
                <Badge variant={caseStudy.difficulty === 'beginner' ? 'secondary' : 
                              caseStudy.difficulty === 'intermediate' ? 'default' : 'destructive'}>
                  {caseStudy.difficulty}
                </Badge>
              </div>
              <p className="text-gray-700 mt-2">{caseStudy.scenario}</p>
            </CardHeader>
            <CardContent>
              <div className="space-y-3">
                {caseStudy.options.map((option) => (
                  <div key={option.id} className="space-y-2">
                    <label className={`flex items-center p-3 border rounded-lg cursor-pointer transition-colors ${
                      selectedAnswer === option.id ? 'border-blue-500 bg-blue-50' : 'border-gray-200 hover:border-gray-300'
                    } ${showResult && option.correct ? 'border-green-500 bg-green-50' : ''}
                    ${showResult && selectedAnswer === option.id && !option.correct ? 'border-red-500 bg-red-50' : ''}`}>
                      <input
                        type="radio"
                        name={caseStudy.id}
                        value={option.id}
                        checked={selectedAnswer === option.id}
                        onChange={() => handleAnswerSelect(caseStudy.id, option.id)}
                        disabled={showResult}
                        className="mr-3"
                      />
                      <span className="flex-1">{option.text}</span>
                      {showResult && option.correct && <CheckCircle className="w-5 h-5 text-green-600" />}
                      {showResult && selectedAnswer === option.id && !option.correct && <XCircle className="w-5 h-5 text-red-600" />}
                    </label>
                    {showResult && selectedAnswer === option.id && (
                      <div className={`p-3 rounded-lg ${option.correct ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>
                        <div className="flex items-start">
                          <AlertTriangle className="w-4 h-4 mt-0.5 mr-2 flex-shrink-0" />
                          <p className="text-sm">{option.explanation}</p>
                        </div>
                      </div>
                    )}
                  </div>
                ))}
              </div>

              <div className="flex gap-2 mt-4">
                {!showResult ? (
                  <Button 
                    onClick={() => handleSubmit(caseStudy.id)}
                    disabled={!selectedAnswer}
                    className="w-full"
                  >
                    Submit Answer
                  </Button>
                ) : (
                  <Button 
                    onClick={() => resetCase(caseStudy.id)}
                    variant="outline"
                    className="w-full"
                  >
                    Try Again
                  </Button>
                )}
              </div>
            </CardContent>
          </Card>
        );
      })}
    </div>
  );
};