import React, { useState } from 'react';
import { AppContext, ExposureSettings } from './appContexts';

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [completedTutorials, setCompletedTutorials] = useState<number[]>([]);
  const [exposureSettings, setExposureSettings] = useState<ExposureSettings>({
    aperture: 5.6,
    shutterSpeed: 125,
    iso: 400
  });

  const toggleSidebar = () => {
    setSidebarOpen(prev => !prev);
  };

  const completeTutorial = (index: number) => {
    if (!completedTutorials.includes(index)) {
      setCompletedTutorials(prev => [...prev, index]);
    }
  };

  return (
    <AppContext.Provider
      value={{
        sidebarOpen,
        toggleSidebar,
        completedTutorials,
        completeTutorial,
        exposureSettings,
        setExposureSettings,
      }}
    >
      {children}
    </AppContext.Provider>
  );
};

