// Advanced cache optimization strategies
import { QueryClient } from '@tanstack/react-query'

interface CacheMetrics {
  hitRate: number
  missRate: number
  memoryUsage: number
  networkLatency: number
  userEngagement: number
}

interface Interaction {
  category?: string;
  timestamp?: number;
  type?: string;
  query?: string;
  [key: string]: unknown;
}

interface OptimizationStrategy {
  name: string
  priority: number
  execute: () => Promise<void>
}

class CacheOptimizer {
  private queryClient: QueryClient
  private metrics: CacheMetrics = {
    hitRate: 0,
    missRate: 0,
    memoryUsage: 0,
    networkLatency: 0,
    userEngagement: 0
  }
  private strategies: OptimizationStrategy[] = []

  constructor(queryClient: QueryClient) {
    this.queryClient = queryClient
    this.initializeStrategies()
    this.startOptimization()
  }

  private initializeStrategies() {
    this.strategies = [
      {
        name: 'predictive-preload',
        priority: 1,
        execute: () => this.predictivePreload()
      },
      {
        name: 'memory-pressure-management',
        priority: 2,
        execute: () => this.manageMemoryPressure()
      },
      {
        name: 'network-aware-caching',
        priority: 3,
        execute: () => this.networkAwareCaching()
      },
      {
        name: 'cache-warming',
        priority: 4,
        execute: () => this.warmCache()
      }
    ]
  }

  private async predictivePreload(): Promise<void> {
    const userBehavior = this.analyzeUserBehavior()
    const predictedQueries = this.predictNextQueries(userBehavior)
    
    for (const query of predictedQueries) {
      await this.queryClient.prefetchQuery({
        queryKey: query.key,
        queryFn: query.fn,
        staleTime: 5 * 60 * 1000
      })
    }
  }

  private async manageMemoryPressure(): Promise<void> {
    const memoryUsage = this.getMemoryUsage()
    if (memoryUsage > 0.8) {
      // Remove least recently used queries
      const cache = this.queryClient.getQueryCache()
      const queries = cache.getAll()
      
      queries
        .sort((a, b) => (a.state.dataUpdatedAt || 0) - (b.state.dataUpdatedAt || 0))
        .slice(0, Math.floor(queries.length * 0.3))
        .forEach(query => cache.remove(query))
    }
  }

  private async networkAwareCaching(): Promise<void> {
    const connection = (navigator as unknown as { connection?: { effectiveType?: string; downlink?: number } }).connection
    if (connection) {
      const { effectiveType, downlink } = connection
      
      if (effectiveType === 'slow-2g' || downlink < 1) {
        // Aggressive caching for slow connections
        this.queryClient.setDefaultOptions({
          queries: {
            staleTime: 15 * 60 * 1000,
            gcTime: 30 * 60 * 1000,
            retry: 1
          }
        })
      } else if (effectiveType === '4g' && downlink > 10) {
        // More frequent updates for fast connections
        this.queryClient.setDefaultOptions({
          queries: {
            staleTime: 2 * 60 * 1000,
            gcTime: 10 * 60 * 1000,
            retry: 3
          }
        })
      }
    }
  }

  private async warmCache(): Promise<void> {
    const criticalQueries = [
      'wildlife-photos',
      'user-favorites',
      'recent-uploads'
    ]
    
    for (const queryKey of criticalQueries) {
      this.queryClient.prefetchQuery({
        queryKey: [queryKey],
        queryFn: () => this.fetchCriticalData(queryKey)
      })
    }
  }

  private analyzeUserBehavior() {
    const interactions: Interaction[] = JSON.parse(localStorage.getItem('user-interactions') || '[]')
    return {
      mostViewedCategories: this.getMostViewedCategories(interactions),
      timePatterns: this.getTimePatterns(interactions),
      searchPatterns: this.getSearchPatterns(interactions)
    }
  }

  private predictNextQueries(behavior: { mostViewedCategories: string[] }) {
    // ML-like prediction based on user behavior
    return behavior.mostViewedCategories.map((category: string) => ({
      key: ['photos', category],
      fn: () => this.fetchPhotosByCategory(category)
    }))
  }

  private getMemoryUsage(): number {
    if ('memory' in performance) {
      const mem = (performance as unknown as { memory?: { usedJSHeapSize?: number; jsHeapSizeLimit?: number } }).memory;
      if (mem && typeof mem.usedJSHeapSize === 'number' && typeof mem.jsHeapSizeLimit === 'number') {
        return mem.usedJSHeapSize / mem.jsHeapSizeLimit;
      }
    }
    return 0.5 // Default assumption
  }

  private getMostViewedCategories(interactions: Interaction[]): string[] {
    const categoryCount = interactions.reduce<Record<string, number>>((acc, interaction) => {
      if (interaction.category) {
        acc[interaction.category] = (acc[interaction.category] || 0) + 1
      }
      return acc
    }, {})
    
    return Object.entries(categoryCount)
      .sort(([,a], [,b]) => (b as number) - (a as number))
      .slice(0, 5)
      .map(([category]) => category)
  }

  private getTimePatterns(interactions: Interaction[]) {
    return interactions.map(i => new Date(i.timestamp || 0).getHours())
  }

  private getSearchPatterns(interactions: Interaction[]) {
    return interactions.filter(i => i.type === 'search').map(i => i.query || '')
  }

  private async fetchCriticalData(queryKey: string) {
    // Simulate API call
    return new Promise(resolve => setTimeout(resolve, 100))
  }

  private async fetchPhotosByCategory(category: string) {
    // Simulate API call
    return new Promise(resolve => setTimeout(resolve, 200))
  }

  private startOptimization() {
    setInterval(() => {
      this.strategies
        .sort((a, b) => a.priority - b.priority)
        .forEach(strategy => strategy.execute().catch(console.error))
    }, 30000) // Run every 30 seconds
  }

  updateMetrics(newMetrics: Partial<CacheMetrics>) {
    this.metrics = { ...this.metrics, ...newMetrics }
  }

  getMetrics(): CacheMetrics {
    return { ...this.metrics }
  }
}

export { CacheOptimizer, type CacheMetrics, type OptimizationStrategy }