import React, { useState, useEffect } from 'react';

interface AnimatedEducationalImageProps {
  src: string;
  alt: string;
  title: string;
  description: string;
  delay?: number;
}

export const AnimatedEducationalImage: React.FC<AnimatedEducationalImageProps> = ({
  src,
  alt,
  title,
  description,
  delay = 0
}) => {
  const [isVisible, setIsVisible] = useState(false);
  const [isHovered, setIsHovered] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => {
      setIsVisible(true);
    }, delay);
    return () => clearTimeout(timer);
  }, [delay]);

  return (
    <div 
      className={`relative overflow-hidden rounded-xl bg-gradient-to-br from-blue-50 to-purple-50 p-6 transition-all duration-1000 transform ${
        isVisible ? 'translate-y-0 opacity-100 scale-100' : 'translate-y-8 opacity-0 scale-95'
      }`}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      <div className={`transition-transform duration-700 ${isHovered ? 'scale-105 rotate-1' : 'scale-100'}`}>
        <img
          src={src}
          alt={alt}
          className="w-full h-48 object-cover rounded-lg shadow-2xl transition-all duration-500"
          style={{
            filter: isHovered ? 'brightness(1.1) saturate(1.2)' : 'brightness(1) saturate(1)',
            transform: isHovered ? 'perspective(1000px) rotateX(5deg)' : 'perspective(1000px) rotateX(0deg)'
          }}
        />
      </div>
      <div className="mt-4 space-y-2">
        <h4 className="text-lg font-bold text-gray-800 transition-colors duration-300">{title}</h4>
        <p className="text-sm text-gray-600">{description}</p>
      </div>
      <div className={`absolute inset-0 bg-gradient-to-r from-blue-400/20 to-purple-400/20 rounded-xl transition-opacity duration-500 ${
        isHovered ? 'opacity-100' : 'opacity-0'
      }`} />
    </div>
  );
};