import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Tabs, TabsContent, TabsList, TabsTrigger } from './ui/tabs';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { CheckCircle, Eye, Camera, Palette, Target } from 'lucide-react';

const EditingApproachModule = () => {
  const [assessmentStep, setAssessmentStep] = useState(0);
  const [checkedItems, setCheckedItems] = useState<number[]>([]);

  const assessmentSteps = [
    { title: "First Impression", icon: Eye, description: "What story does this image tell?" },
    { title: "Technical Analysis", icon: Camera, description: "Evaluate exposure, focus, composition" },
    { title: "Creative Potential", icon: Palette, description: "Identify enhancement opportunities" },
    { title: "Edit Planning", icon: Target, description: "Define your editing goals" }
  ];

  const examples = [
    {
      image: "https://d64gsuwffb70l.cloudfront.net/68b40c5bc1c21df39a5bc0f2_1757009587359_e02b74c5.webp",
      title: "Forest Fox",
      assessment: "Good composition, needs contrast boost, story: curious wildlife"
    },
    {
      image: "https://d64gsuwffb70l.cloudfront.net/68b40c5bc1c21df39a5bc0f2_1757009590966_8806f152.webp",
      title: "Eagle Flight",
      assessment: "Underexposed, motion blur, story: power and freedom"
    },
    {
      image: "https://d64gsuwffb70l.cloudfront.net/68b40c5bc1c21df39a5bc0f2_1757009594502_b954bb7e.webp",
      title: "Golden Hour Deer",
      assessment: "Excellent foundation, enhance warmth, story: peaceful moment"
    }
  ];

  const checklistItems = [
    "Is the subject properly exposed?",
    "Are the eyes sharp and in focus?",
    "Does the composition support the story?",
    "What mood should this convey?",
    "Are there distracting elements?",
    "What's the strongest feature to enhance?"
  ];

  return (
    <div className="max-w-6xl mx-auto p-6">
      <div className="mb-8">
        <h1 className="text-3xl font-bold mb-4">How To Approach An Edit</h1>
        <p className="text-gray-600">Master the essential pre-editing assessment process</p>
      </div>

      <Tabs defaultValue="process" className="w-full">
        <TabsList className="grid w-full grid-cols-4">
          <TabsTrigger value="process">Assessment Process</TabsTrigger>
          <TabsTrigger value="examples">Image Examples</TabsTrigger>
          <TabsTrigger value="checklist">Evaluation Checklist</TabsTrigger>
          <TabsTrigger value="workflow">Edit Planning</TabsTrigger>
        </TabsList>

        <TabsContent value="process" className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            {assessmentSteps.map((step, index) => {
              const Icon = step.icon;
              return (
                <Card key={index} className={`cursor-pointer transition-all ${assessmentStep === index ? 'ring-2 ring-blue-500' : ''}`}
                      onClick={() => setAssessmentStep(index)}>
                  <CardHeader className="text-center">
                    <Icon className="w-8 h-8 mx-auto mb-2 text-blue-600" />
                    <CardTitle className="text-lg">{step.title}</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <p className="text-sm text-gray-600">{step.description}</p>
                  </CardContent>
                </Card>
              );
            })}
          </div>
        </TabsContent>

        <TabsContent value="examples" className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {examples.map((example, index) => (
              <Card key={index}>
                <CardHeader>
                  <img src={example.image} alt={example.title} className="w-full h-48 object-cover rounded-lg" />
                  <CardTitle>{example.title}</CardTitle>
                </CardHeader>
                <CardContent>
                  <p className="text-sm text-gray-600">{example.assessment}</p>
                </CardContent>
              </Card>
            ))}
          </div>
        </TabsContent>

        <TabsContent value="checklist" className="space-y-6">
          <Card>
            <CardHeader>
              <CardTitle>Pre-Edit Assessment Checklist</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-3">
                {checklistItems.map((item, index) => (
                  <div key={index} className="flex items-center space-x-3">
                    <Button
                      variant={checkedItems.includes(index) ? "default" : "outline"}
                      size="sm"
                      onClick={() => {
                        if (checkedItems.includes(index)) {
                          setCheckedItems(checkedItems.filter(i => i !== index));
                        } else {
                          setCheckedItems([...checkedItems, index]);
                        }
                      }}
                    >
                      <CheckCircle className="w-4 h-4" />
                    </Button>
                    <span className={checkedItems.includes(index) ? 'line-through text-gray-500' : ''}>{item}</span>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="workflow" className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <Card>
              <CardHeader>
                <CardTitle>Story-First Approach</CardTitle>
              </CardHeader>
              <CardContent className="space-y-3">
                <Badge variant="outline">Step 1: Identify the emotion</Badge>
                <Badge variant="outline">Step 2: Enhance the mood</Badge>
                <Badge variant="outline">Step 3: Guide the viewer's eye</Badge>
                <Badge variant="outline">Step 4: Maintain authenticity</Badge>
              </CardContent>
            </Card>
            
            <Card>
              <CardHeader>
                <CardTitle>Technical Foundation</CardTitle>
              </CardHeader>
              <CardContent className="space-y-3">
                <Badge variant="secondary">Exposure correction first</Badge>
                <Badge variant="secondary">Focus on the eyes</Badge>
                <Badge variant="secondary">Balance highlights/shadows</Badge>
                <Badge variant="secondary">Color temperature adjustment</Badge>
              </CardContent>
            </Card>
          </div>
        </TabsContent>
      </Tabs>
    </div>
  );
};

export default EditingApproachModule;