import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Slider } from './ui/slider';
import { Badge } from './ui/badge';

const DepthOfFieldSimulator = () => {
  const [aperture, setAperture] = useState([2.8]);
  const [distance, setDistance] = useState([5]);
  const [focalLength, setFocalLength] = useState([85]);

  const apertureValues = [1.4, 2, 2.8, 4, 5.6, 8, 11, 16];
  const currentAperture = apertureValues[Math.round(aperture[0])];
  
  // Calculate depth of field effect
  const blurIntensity = Math.max(1, 8 - aperture[0]);
  const dofRange = Math.max(20, 100 - (aperture[0] * 10) - (distance[0] * 2));

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <span className="text-2xl">📷</span>
            Depth of Field Simulator
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Controls */}
          <div className="grid md:grid-cols-3 gap-4">
            <div>
              <label className="text-sm font-medium mb-2 block">
                Aperture: f/{currentAperture}
              </label>
              <Slider
                value={aperture}
                onValueChange={setAperture}
                max={7}
                min={0}
                step={0.1}
                className="w-full"
              />
            </div>
            <div>
              <label className="text-sm font-medium mb-2 block">
                Distance: {distance[0]}m
              </label>
              <Slider
                value={distance}
                onValueChange={setDistance}
                max={20}
                min={1}
                step={0.5}
                className="w-full"
              />
            </div>
            <div>
              <label className="text-sm font-medium mb-2 block">
                Focal Length: {focalLength[0]}mm
              </label>
              <Slider
                value={focalLength}
                onValueChange={setFocalLength}
                max={200}
                min={24}
                step={1}
                className="w-full"
              />
            </div>
          </div>

          {/* Visual Preview */}
          <div className="relative h-64 bg-gradient-to-b from-green-100 to-green-200 rounded-lg overflow-hidden">
            {/* Background (blurred) */}
            <div 
              className="absolute inset-0 bg-gradient-to-r from-blue-200 to-purple-200"
              style={{ filter: `blur(${blurIntensity}px)` }}
            >
              <div className="absolute top-4 left-4 w-8 h-8 bg-yellow-400 rounded-full"></div>
              <div className="absolute top-8 right-8 w-6 h-6 bg-red-400 rounded-full"></div>
              <div className="absolute bottom-4 left-8 w-4 h-4 bg-blue-400 rounded-full"></div>
            </div>
            
            {/* Subject (in focus) */}
            <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2">
              <div className="w-16 h-16 bg-orange-500 rounded-full border-4 border-white shadow-lg flex items-center justify-center">
                <span className="text-white text-xl">🦅</span>
              </div>
            </div>
            
            {/* Foreground (blurred) */}
            <div 
              className="absolute bottom-0 left-0 right-0 h-16 bg-green-600 opacity-70"
              style={{ filter: `blur(${blurIntensity * 0.8}px)` }}
            ></div>
          </div>

          {/* Info Panel */}
          <div className="grid md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <Badge variant="outline">Depth of Field: ~{dofRange}cm</Badge>
              <p className="text-sm text-gray-600">
                {currentAperture < 2.8 ? "Very shallow DOF - Great for portraits" :
                 currentAperture < 5.6 ? "Moderate DOF - Good for single subjects" :
                 "Deep DOF - Ideal for landscapes"}
              </p>
            </div>
            <div className="space-y-2">
              <Badge variant="outline">Background Blur: {blurIntensity.toFixed(1)}x</Badge>
              <p className="text-sm text-gray-600">
                {distance[0] < 3 ? "Close subject - Enhanced bokeh effect" :
                 distance[0] < 10 ? "Medium distance - Balanced composition" :
                 "Far subject - Reduced background separation"}
              </p>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

export default DepthOfFieldSimulator;