import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Target, Eye, Crosshair } from 'lucide-react';

export default function FocusSimulator() {
  const [focusMode, setFocusMode] = useState('single');
  const [focusPoint, setFocusPoint] = useState({ x: 50, y: 50 });
  const [isTracking, setIsTracking] = useState(false);

  const focusModes = [
    { id: 'single', name: 'Single AF', desc: 'Best for stationary subjects' },
    { id: 'continuous', name: 'Continuous AF', desc: 'Tracks moving subjects' },
    { id: 'automatic', name: 'Auto AF', desc: 'Camera decides focus mode' }
  ];

  const handleImageClick = (e: React.MouseEvent<HTMLDivElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 100;
    const y = ((e.clientY - rect.top) / rect.height) * 100;
    setFocusPoint({ x, y });
    
    if (focusMode === 'continuous') {
      setIsTracking(true);
      setTimeout(() => setIsTracking(false), 2000);
    }
  };

  return (
    <Card className="w-full max-w-4xl mx-auto">
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Target className="h-6 w-6" />
          Focus System Simulator
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-6">
        <div className="grid md:grid-cols-3 gap-4">
          {focusModes.map((mode) => (
            <Button
              key={mode.id}
              variant={focusMode === mode.id ? 'default' : 'outline'}
              onClick={() => setFocusMode(mode.id)}
              className="h-auto p-4 flex-col items-start"
            >
              <div className="font-medium">{mode.name}</div>
              <div className="text-xs text-muted-foreground mt-1">{mode.desc}</div>
            </Button>
          ))}
        </div>

        <div 
          className="relative bg-gradient-to-br from-green-100 to-green-200 rounded-lg h-64 cursor-crosshair overflow-hidden"
          onClick={handleImageClick}
        >
          <div className="absolute inset-0 bg-gray-100 opacity-30"></div>
          
          {/* Simulated wildlife subjects */}
          <div className="absolute top-4 left-8 w-8 h-8 bg-amber-600 rounded-full opacity-80"></div>
          <div className="absolute top-12 right-12 w-6 h-6 bg-brown-600 rounded-full opacity-70"></div>
          <div className="absolute bottom-8 left-1/3 w-10 h-10 bg-gray-700 rounded-full opacity-90"></div>

          {/* Focus point indicator */}
          <div 
            className={`absolute w-12 h-12 border-2 ${isTracking ? 'border-green-500 animate-pulse' : 'border-red-500'} rounded-full pointer-events-none transition-all duration-300`}
            style={{ 
              left: `${focusPoint.x}%`, 
              top: `${focusPoint.y}%`,
              transform: 'translate(-50%, -50%)'
            }}
          >
            <Crosshair className="w-4 h-4 absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2" />
          </div>
        </div>

        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Eye className="h-4 w-4" />
            <span className="text-sm">Focus Status:</span>
            <Badge variant={isTracking ? 'default' : 'secondary'}>
              {isTracking ? 'Tracking' : 'Locked'}
            </Badge>
          </div>
          <div className="text-sm text-muted-foreground">
            Click on the scene to set focus point
          </div>
        </div>
      </CardContent>
    </Card>
  );
}