import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Upload, Camera, ShieldCheck, Loader2 } from 'lucide-react';
import { extractMetadata, PhotoMetadata } from '@/utils/metadataExtraction';
import { MetadataAnalyzer } from '@/components/MetadataAnalyzer';

// Normalise raw EXIF strings into the bare numeric formats MetadataAnalyzer renders
function normalise(m: PhotoMetadata): PhotoMetadata & { dateTime?: string } {
  const bare = (v?: string) => (v ? v.replace(/^f\/?/i, '').replace(/\s*mm$/i, '').trim() : undefined);
  return {
    ...m,
    aperture: bare(m.aperture),
    focalLength: bare(m.focalLength),
    iso: m.iso ? String(m.iso).replace(/^ISO\s*/i, '') : undefined,
    dateTime: m.timestamp ? new Date(m.timestamp).toLocaleString() : undefined,
  } as PhotoMetadata & { dateTime?: string };
}

const PhotoAnalyzerTool: React.FC = () => {
  const [preview, setPreview] = useState<string | null>(null);
  const [metadata, setMetadata] = useState<(PhotoMetadata & { dateTime?: string }) | null>(null);
  const [fileName, setFileName] = useState<string>('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const onFile = async (file: File | undefined | null) => {
    if (!file) return;
    setBusy(true);
    setError(null);
    setFileName(file.name);
    try {
      const url = URL.createObjectURL(file);
      setPreview((old) => {
        if (old) URL.revokeObjectURL(old);
        return url;
      });
      const meta = await extractMetadata(file);
      setMetadata(normalise(meta));
    } catch (e) {
      setError('Could not read this photo. Try a JPEG straight from your camera or phone.');
      setMetadata(null);
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="w-full max-w-4xl mx-auto p-4 space-y-6">
      <Card>
        <CardHeader className="text-center">
          <CardTitle className="text-2xl font-bold flex items-center justify-center gap-2">
            <Camera className="h-7 w-7 text-green-700" /> Photo Settings Analyzer
          </CardTitle>
          <p className="text-muted-foreground">
            Upload one of your own wildlife shots. The Lab reads the camera settings hidden
            inside the file and explains what they mean — aperture, shutter speed, ISO and more.
          </p>
          <p className="text-xs text-muted-foreground flex items-center justify-center gap-1">
            <ShieldCheck className="h-4 w-4 text-green-700" />
            Your photo is analysed on your own device only — it is never uploaded anywhere.
          </p>
        </CardHeader>
        <CardContent className="space-y-4">
          <label className="block border-2 border-dashed border-green-700/40 rounded-xl p-8 text-center cursor-pointer hover:bg-green-50 transition-colors">
            <input
              id="photo-analyzer-input"
              type="file"
              accept="image/jpeg,image/png,image/tiff,image/webp"
              className="hidden"
              onChange={(e) => onFile(e.target.files?.[0])}
            />
            <Upload className="h-8 w-8 mx-auto mb-2 text-green-700" />
            <span className="font-semibold text-green-900">Choose a photo</span>
            <span className="block text-sm text-muted-foreground mt-1">
              JPEG straight from the camera keeps the most information
            </span>
          </label>

          {busy && (
            <div className="flex items-center justify-center gap-2 text-muted-foreground">
              <Loader2 className="h-5 w-5 animate-spin" /> Reading camera settings…
            </div>
          )}
          {error && <p className="text-center text-red-700 text-sm">{error}</p>}

          {preview && !busy && (
            <div className="text-center space-y-2">
              <img
                src={preview}
                alt={fileName || 'Uploaded wildlife photo'}
                className="max-h-80 mx-auto rounded-lg shadow-md"
              />
              {fileName && <p className="text-xs text-muted-foreground">{fileName}</p>}
            </div>
          )}
        </CardContent>
      </Card>

      {metadata && !busy && (
        <>
          {!metadata.aperture && !metadata.iso && !metadata.shutterSpeed ? (
            <Card>
              <CardContent className="py-6 text-center text-muted-foreground text-sm">
                This image carries no camera settings — screenshots and photos sent through
                WhatsApp lose them. Try the original file from your camera or phone gallery.
              </CardContent>
            </Card>
          ) : (
            <MetadataAnalyzer metadata={metadata} />
          )}
          <div className="text-center">
            <Button
              variant="outline"
              onClick={() => {
                setMetadata(null);
                setPreview((old) => {
                  if (old) URL.revokeObjectURL(old);
                  return null;
                });
                setFileName('');
              }}
            >
              Analyse another photo
            </Button>
          </div>
        </>
      )}
    </div>
  );
};

export default PhotoAnalyzerTool;
