import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Slider } from './ui/slider';
import { Sun, Moon, Cloud, Sunrise, Sunset } from 'lucide-react';

export default function LightingSimulator() {
  const [timeOfDay, setTimeOfDay] = useState('golden-hour');
  const [weather, setWeather] = useState('clear');
  const [intensity, setIntensity] = useState([70]);

  const lightingConditions = [
    { id: 'sunrise', name: 'Sunrise', icon: Sunrise, color: 'from-orange-300 to-yellow-200' },
    { id: 'golden-hour', name: 'Golden Hour', icon: Sun, color: 'from-yellow-400 to-orange-300' },
    { id: 'midday', name: 'Midday', icon: Sun, color: 'from-blue-200 to-white' },
    { id: 'sunset', name: 'Sunset', icon: Sunset, color: 'from-red-400 to-orange-400' },
    { id: 'blue-hour', name: 'Blue Hour', icon: Moon, color: 'from-blue-600 to-purple-400' }
  ];

  const weatherConditions = [
    { id: 'clear', name: 'Clear', effect: 'Sharp shadows, high contrast' },
    { id: 'cloudy', name: 'Cloudy', effect: 'Soft, diffused light' },
    { id: 'overcast', name: 'Overcast', effect: 'Even lighting, low contrast' },
    { id: 'fog', name: 'Fog', effect: 'Mysterious, muted tones' }
  ];

  const getCurrentCondition = () => {
    return lightingConditions.find(c => c.id === timeOfDay);
  };

  const getRecommendation = () => {
    const recommendations = {
      'sunrise': 'Perfect for silhouettes and dramatic landscapes. Use spot metering.',
      'golden-hour': 'Ideal for wildlife portraits. Warm, flattering light.',
      'midday': 'Challenging harsh light. Seek shade or use fill flash.',
      'sunset': 'Great for backlit subjects. Watch for lens flare.',
      'blue-hour': 'Use tripod for longer exposures. Capture ambient light.'
    };
    return recommendations[timeOfDay as keyof typeof recommendations];
  };

  const currentCondition = getCurrentCondition();

  return (
    <Card className="w-full max-w-4xl mx-auto">
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Sun className="h-6 w-6" />
          Lighting Conditions Simulator
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-6">
        <div className="grid md:grid-cols-5 gap-3">
          {lightingConditions.map((condition) => {
            const IconComponent = condition.icon;
            return (
              <Button
                key={condition.id}
                variant={timeOfDay === condition.id ? 'default' : 'outline'}
                onClick={() => setTimeOfDay(condition.id)}
                className="h-auto p-3 flex-col"
              >
                <IconComponent className="h-5 w-5 mb-1" />
                <span className="text-xs">{condition.name}</span>
              </Button>
            );
          })}
        </div>

        <div className="space-y-3">
          <div className="flex items-center gap-2">
            <span className="font-medium">Weather:</span>
            <div className="flex gap-2">
              {weatherConditions.map((w) => (
                <Button
                  key={w.id}
                  variant={weather === w.id ? 'default' : 'outline'}
                  size="sm"
                  onClick={() => setWeather(w.id)}
                >
                  {w.name}
                </Button>
              ))}
            </div>
          </div>
          
          <div className="space-y-2">
            <div className="flex items-center gap-2">
              <span className="font-medium">Light Intensity:</span>
              <Badge variant="outline">{intensity[0]}%</Badge>
            </div>
            <Slider
              value={intensity}
              onValueChange={setIntensity}
              max={100}
              min={10}
              step={10}
              className="w-full"
            />
          </div>
        </div>

        <div 
          className={`relative rounded-lg h-64 bg-gradient-to-br ${currentCondition?.color} overflow-hidden`}
          style={{ opacity: intensity[0] / 100 }}
        >
          {weather === 'cloudy' && (
            <div className="absolute inset-0 bg-white opacity-30"></div>
          )}
          {weather === 'overcast' && (
            <div className="absolute inset-0 bg-gray-400 opacity-40"></div>
          )}
          {weather === 'fog' && (
            <div className="absolute inset-0 bg-gray-200 opacity-60"></div>
          )}
          
          {/* Simulated wildlife scene */}
          <div className="absolute bottom-8 left-8 w-8 h-12 bg-black opacity-60 rounded-t-full"></div>
          <div className="absolute bottom-12 right-12 w-6 h-6 bg-brown-600 rounded-full"></div>
          <div className="absolute top-8 left-1/3 w-4 h-4 bg-yellow-600 rounded-full"></div>
          
          {/* Light direction indicator */}
          <div className="absolute top-4 right-4 text-white text-xs bg-black bg-opacity-50 px-2 py-1 rounded">
            {timeOfDay === 'midday' ? '↓ Overhead' : '← Side Light'}
          </div>
        </div>

        <div className="space-y-2">
          <div className="flex items-center gap-2">
            <Badge variant="secondary">{currentCondition?.name}</Badge>
            <Badge variant="outline">{weatherConditions.find(w => w.id === weather)?.name}</Badge>
          </div>
          <div className="text-sm bg-muted p-3 rounded">
            <strong>Photography Tip:</strong> {getRecommendation()}
          </div>
          <div className="text-xs text-muted-foreground">
            <strong>Weather Effect:</strong> {weatherConditions.find(w => w.id === weather)?.effect}
          </div>
        </div>
      </CardContent>
    </Card>
  );
}