import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Progress } from '@/components/ui/progress';
import { Badge } from '@/components/ui/badge';
import { CheckCircle, XCircle, Award, RotateCcw } from 'lucide-react';
import { supabase } from '@/lib/supabase';

interface Question {
  id: string;
  question: string;
  options: string[];
  correctAnswer: number;
  explanation: string;
}

const ethicsQuestions: Question[] = [
  {
    id: 'q1',
    question: 'What is the minimum safe distance to maintain from elephants in South African parks?',
    options: ['10 meters', '25 meters', 'Stay in vehicle', '50 meters'],
    correctAnswer: 2,
    explanation: 'Always stay in your vehicle when viewing elephants in South African national parks for safety.'
  },
  {
    id: 'q2',
    question: 'When should you use flash photography in wildlife settings?',
    options: ['At night for better visibility', 'Never', 'Only with small animals', 'During golden hour'],
    correctAnswer: 1,
    explanation: 'Flash photography should never be used as it can startle and disorient animals.'
  },
  {
    id: 'q3',
    question: 'What should you do before sharing photos of endangered species online?',
    options: ['Add location tags', 'Remove geolocation data', 'Wait 6 months', 'Get park permission'],
    correctAnswer: 1,
    explanation: 'Always remove geolocation data to protect endangered animals from poachers.'
  },
  {
    id: 'q4',
    question: 'How should you approach a sleeping animal for photography?',
    options: ['Make noise to wake it', 'Get as close as possible', 'Leave it undisturbed', 'Use flash to see better'],
    correctAnswer: 2,
    explanation: 'Sleeping animals should be left undisturbed. Never try to wake them for a photo.'
  },
  {
    id: 'q5',
    question: 'What is the best time for wildlife photography in South Africa?',
    options: ['Midday sun', 'Golden hours (dawn/dusk)', 'Night only', 'Rainy weather'],
    correctAnswer: 1,
    explanation: 'Golden hours provide the best light and animals are most active during these times.'
  }
];

export const EthicsAssessment: React.FC = () => {
  const [currentQuestion, setCurrentQuestion] = useState(0);
  const [answers, setAnswers] = useState<number[]>([]);
  const [showResults, setShowResults] = useState(false);
  const [score, setScore] = useState(0);

  const handleAnswer = (answerIndex: number) => {
    const newAnswers = [...answers];
    newAnswers[currentQuestion] = answerIndex;
    setAnswers(newAnswers);

    if (currentQuestion < ethicsQuestions.length - 1) {
      setCurrentQuestion(currentQuestion + 1);
    } else {
      calculateScore(newAnswers);
    }
  };

  const calculateScore = async (finalAnswers: number[]) => {
    const correctAnswers = finalAnswers.filter((answer, index) => 
      answer === ethicsQuestions[index].correctAnswer
    ).length;
    
    const finalScore = Math.round((correctAnswers / ethicsQuestions.length) * 100);
    setScore(finalScore);
    setShowResults(true);

    // Save assessment result to database
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (user) {
        await supabase.from('assessments').insert({
          user_id: user.id,
          assessment_type: 'ethics',
          score: finalScore,
          total_questions: ethicsQuestions.length,
          correct_answers: correctAnswers,
          completed_at: new Date().toISOString()
        });
      }
    } catch (error) {
      console.error('Error saving assessment:', error);
    }
  };

  const resetAssessment = () => {
    setCurrentQuestion(0);
    setAnswers([]);
    setShowResults(false);
    setScore(0);
  };

  const getScoreColor = (score: number) => {
    if (score >= 80) return 'text-green-600';
    if (score >= 60) return 'text-yellow-600';
    return 'text-red-600';
  };

  const getScoreBadge = (score: number) => {
    if (score >= 80) return { text: 'Excellent', variant: 'default' as const };
    if (score >= 60) return { text: 'Good', variant: 'secondary' as const };
    return { text: 'Needs Improvement', variant: 'destructive' as const };
  };

  if (showResults) {
    const badge = getScoreBadge(score);
    
    return (
      <Card className="w-full max-w-2xl mx-auto">
        <CardHeader className="text-center">
          <div className="flex justify-center mb-4">
            <Award className="w-16 h-16 text-yellow-500" />
          </div>
          <CardTitle className="text-2xl">Assessment Complete!</CardTitle>
        </CardHeader>
        <CardContent className="text-center space-y-6">
          <div>
            <div className={`text-4xl font-bold ${getScoreColor(score)}`}>
              {score}%
            </div>
            <Badge variant={badge.variant} className="mt-2">
              {badge.text}
            </Badge>
          </div>
          
          <div className="space-y-4">
            <p className="text-gray-600">
              You answered {answers.filter((answer, index) => answer === ethicsQuestions[index].correctAnswer).length} out of {ethicsQuestions.length} questions correctly.
            </p>
            
            {score < 80 && (
              <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4">
                <p className="text-yellow-800 text-sm">
                  Consider reviewing the ethics guide and trying the interactive case studies to improve your understanding.
                </p>
              </div>
            )}
          </div>

          <div className="space-y-4">
            {ethicsQuestions.map((question, index) => (
              <div key={question.id} className="text-left border rounded-lg p-4">
                <div className="flex items-start gap-2 mb-2">
                  {answers[index] === question.correctAnswer ? (
                    <CheckCircle className="w-5 h-5 text-green-600 mt-0.5" />
                  ) : (
                    <XCircle className="w-5 h-5 text-red-600 mt-0.5" />
                  )}
                  <div className="flex-1">
                    <p className="font-medium text-sm">{question.question}</p>
                    <p className="text-sm text-gray-600 mt-1">
                      Your answer: {question.options[answers[index]]}
                    </p>
                    {answers[index] !== question.correctAnswer && (
                      <p className="text-sm text-green-600 mt-1">
                        Correct: {question.options[question.correctAnswer]}
                      </p>
                    )}
                    <p className="text-xs text-gray-500 mt-2">{question.explanation}</p>
                  </div>
                </div>
              </div>
            ))}
          </div>

          <Button onClick={resetAssessment} className="w-full">
            <RotateCcw className="w-4 h-4 mr-2" />
            Retake Assessment
          </Button>
        </CardContent>
      </Card>
    );
  }

  const progress = ((currentQuestion + 1) / ethicsQuestions.length) * 100;
  const question = ethicsQuestions[currentQuestion];

  return (
    <Card className="w-full max-w-2xl mx-auto">
      <CardHeader>
        <div className="flex justify-between items-center mb-4">
          <CardTitle>Ethics Assessment</CardTitle>
          <Badge variant="outline">
            {currentQuestion + 1} of {ethicsQuestions.length}
          </Badge>
        </div>
        <Progress value={progress} className="w-full" />
      </CardHeader>
      <CardContent>
        <div className="space-y-6">
          <h3 className="text-lg font-medium">{question.question}</h3>
          
          <div className="space-y-3">
            {question.options.map((option, index) => (
              <Button
                key={index}
                variant="outline"
                className="w-full text-left justify-start h-auto p-4 hover:bg-blue-50"
                onClick={() => handleAnswer(index)}
              >
                {option}
              </Button>
            ))}
          </div>
        </div>
      </CardContent>
    </Card>
  );
};

export default EthicsAssessment;