import React, { createContext, useContext } from 'react';

export interface ExposureSettings {
  aperture: number;
  shutterSpeed: number;
  iso: number;
}

export interface AppContextType {
  sidebarOpen: boolean;
  toggleSidebar: () => void;
  completedTutorials: number[];
  completeTutorial: (index: number) => void;
  exposureSettings: ExposureSettings;
  setExposureSettings: (settings: ExposureSettings) => void;
}

export const defaultAppContext: AppContextType = {
  sidebarOpen: false,
  toggleSidebar: () => {},
  completedTutorials: [],
  completeTutorial: () => {},
  exposureSettings: { aperture: 5.6, shutterSpeed: 125, iso: 400 },
  setExposureSettings: () => {},
};

export const AppContext = createContext<AppContextType>(defaultAppContext);

export const useAppContext = () => {
  const context = useContext(AppContext);
  if (!context) {
    console.warn('useAppContext must be used within AppProvider, returning default values');
    return defaultAppContext;
  }

  const safeExposureSettings = {
    aperture: 5.6,
    shutterSpeed: 125,
    iso: 400,
    ...context.exposureSettings
  };

  return {
    ...context,
    exposureSettings: safeExposureSettings
  };
};
