import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Slider } from './ui/slider';
import { Badge } from './ui/badge';
import { Button } from './ui/button';

const MotionBlurSimulator = () => {
  const [shutterSpeed, setShutterSpeed] = useState([5]);
  const [subjectSpeed, setSubjectSpeed] = useState([3]);
  const [panningMode, setPanningMode] = useState(false);
  const [isAnimating, setIsAnimating] = useState(false);

  const shutterSpeeds = ['1/2000', '1/1000', '1/500', '1/250', '1/125', '1/60', '1/30', '1/15', '1/8', '1/4'];
  const currentShutter = shutterSpeeds[Math.round(shutterSpeed[0])];
  
  // Calculate motion blur effect
  const blurAmount = Math.max(0, (10 - shutterSpeed[0]) * subjectSpeed[0] * 0.5);
  const freezeMotion = shutterSpeed[0] > 7;

  const startAnimation = () => {
    setIsAnimating(true);
    setTimeout(() => setIsAnimating(false), 2000);
  };

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <span className="text-2xl">🏃</span>
            Motion Blur Simulator
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Controls */}
          <div className="grid md:grid-cols-3 gap-4">
            <div>
              <label className="text-sm font-medium mb-2 block">
                Shutter Speed: {currentShutter}s
              </label>
              <Slider
                value={shutterSpeed}
                onValueChange={setShutterSpeed}
                max={9}
                min={0}
                step={0.1}
                className="w-full"
              />
            </div>
            <div>
              <label className="text-sm font-medium mb-2 block">
                Subject Speed: {subjectSpeed[0]}x
              </label>
              <Slider
                value={subjectSpeed}
                onValueChange={setSubjectSpeed}
                max={10}
                min={1}
                step={0.5}
                className="w-full"
              />
            </div>
            <div className="flex flex-col gap-2">
              <Button
                variant={panningMode ? "default" : "outline"}
                onClick={() => setPanningMode(!panningMode)}
                className="text-sm"
              >
                {panningMode ? "Panning ON" : "Panning OFF"}
              </Button>
              <Button onClick={startAnimation} variant="secondary" className="text-sm">
                Simulate Shot
              </Button>
            </div>
          </div>

          {/* Visual Preview */}
          <div className="relative h-64 bg-gradient-to-r from-blue-100 to-green-100 rounded-lg overflow-hidden">
            {/* Background */}
            <div className={`absolute inset-0 bg-gradient-to-r from-gray-300 to-gray-400 ${
              panningMode && isAnimating ? 'transform translate-x-4 transition-transform duration-1000' : ''
            }`}>
              <div className="absolute top-8 left-8 w-12 h-20 bg-green-600 rounded"></div>
              <div className="absolute top-12 right-12 w-8 h-16 bg-brown-600 rounded"></div>
              <div className="absolute bottom-8 left-1/3 w-6 h-12 bg-red-600 rounded"></div>
            </div>
            
            {/* Moving Subject */}
            <div className={`absolute top-1/2 transform -translate-y-1/2 transition-all duration-2000 ${
              isAnimating ? 'left-3/4' : 'left-1/4'
            }`}>
              <div 
                className="w-12 h-8 bg-yellow-500 rounded-full flex items-center justify-center"
                style={{ 
                  filter: freezeMotion ? 'none' : `blur(${blurAmount}px)`,
                  transform: !panningMode && !freezeMotion ? `scaleX(${1 + blurAmount * 0.2})` : 'none'
                }}
              >
                <span className="text-sm">🦌</span>
              </div>
              {/* Motion trail */}
              {!freezeMotion && (
                <div 
                  className="absolute top-0 right-full h-full bg-yellow-300 opacity-50"
                  style={{ width: `${blurAmount * 4}px` }}
                ></div>
              )}
            </div>
          </div>

          {/* Info Panel */}
          <div className="grid md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <Badge variant="outline">
                Motion Effect: {freezeMotion ? "Frozen" : blurAmount > 5 ? "Heavy Blur" : "Light Blur"}
              </Badge>
              <p className="text-sm text-gray-600">
                {freezeMotion ? "Fast shutter freezes motion completely" :
                 blurAmount > 5 ? "Slow shutter creates artistic motion blur" :
                 "Moderate blur shows movement while maintaining detail"}
              </p>
            </div>
            <div className="space-y-2">
              <Badge variant="outline">
                Technique: {panningMode ? "Panning" : "Static"}
              </Badge>
              <p className="text-sm text-gray-600">
                {panningMode ? "Following subject keeps it sharp, blurs background" :
                 "Static camera captures full motion blur effect"}
              </p>
            </div>
          </div>

          {/* Tips */}
          <div className="bg-blue-50 p-4 rounded-lg">
            <h4 className="font-medium mb-2">Wildlife Photography Tips:</h4>
            <ul className="text-sm space-y-1 text-gray-700">
              <li>• Use 1/500s+ for flying birds</li>
              <li>• Try 1/60s with panning for running animals</li>
              <li>• Slower speeds (1/15s) create artistic water motion</li>
              <li>• Image stabilization helps with slower speeds</li>
            </ul>
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

export default MotionBlurSimulator;