import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { CheckCircle, Circle, Play } from 'lucide-react';

interface TutorialCardProps {
  tutorial: {
    title: string;
    description?: string;
    content?: string;
    preset?: { aperture: string; shutter: string; iso: string };
    tip?: string;
    image?: string;
    tasks?: string[];
  };
  index: number;
  isCompleted: boolean;
  onComplete: (index: number) => void;
}

const TutorialCard: React.FC<TutorialCardProps> = ({ tutorial, index, isCompleted, onComplete }) => {
  const [completedTasks, setCompletedTasks] = useState<number[]>([]);

  const toggleTask = (taskIndex: number) => {
    if (completedTasks.includes(taskIndex)) {
      setCompletedTasks(completedTasks.filter(i => i !== taskIndex));
    } else {
      setCompletedTasks([...completedTasks, taskIndex]);
    }
  };

  return (
    <Card className={`${isCompleted ? 'bg-green-50 border-green-200' : 'hover:shadow-lg'} transition-all duration-300`}>
      <CardHeader>
        <div className="flex items-center justify-between">
          <CardTitle className="text-lg flex items-center gap-2">
            <Play className="w-5 h-5 text-blue-600" />
            {tutorial.title}
          </CardTitle>
          {isCompleted && <Badge className="bg-green-100 text-green-800">Completed</Badge>}
        </div>
      </CardHeader>
      <CardContent>
        <div className={`grid ${tutorial.image ? 'md:grid-cols-2' : ''} gap-4 mb-4`}>
          {tutorial.image && (
            <div>
              <img
                src={tutorial.image}
                alt={tutorial.title}
                className="w-full h-32 object-cover rounded-lg"
              />
            </div>
          )}
          <div className="space-y-2">
            <p className="text-sm">{tutorial.content ?? tutorial.description}</p>
            <div className="bg-gray-100 p-2 rounded text-xs">
              <strong>Settings:</strong> {tutorial.preset?.aperture ?? 'f/5.6'} • {tutorial.preset?.shutter ?? '1/250s'} • ISO {tutorial.preset?.iso ?? '400'}
            </div>
          </div>
        </div>

        <div className="mb-4">
          <h4 className="font-semibold mb-2 text-sm">Practice Tasks:</h4>
          <div className="space-y-2">
            {(tutorial.tasks ?? []).map((task, taskIndex) => (
              <div key={taskIndex} className="flex items-center gap-2 text-sm">
                <button onClick={() => toggleTask(taskIndex)} className="flex-shrink-0">
                  {completedTasks.includes(taskIndex) ? 
                    <CheckCircle className="w-4 h-4 text-green-600" /> : 
                    <Circle className="w-4 h-4 text-gray-400" />
                  }
                </button>
                <span className={completedTasks.includes(taskIndex) ? 'line-through text-gray-500' : ''}>{task}</span>
              </div>
            ))}
          </div>
        </div>

        {tutorial.tip && (
          <div className="bg-blue-50 p-3 rounded mb-4">
            <p className="text-sm text-blue-800">💡 <strong>Tip:</strong> {tutorial.tip}</p>
          </div>
        )}

        <Button onClick={() => onComplete(index)} className="w-full">
          {isCompleted ? 'Review Again' : 'Mark Complete'}
        </Button>
      </CardContent>
    </Card>
  );
};

export default TutorialCard;
export { TutorialCard };