import { QueryClient } from '@tanstack/react-query'
import { CacheOptimizer } from './cacheOptimizer'
import { NetworkOptimizer } from './networkOptimizer'

// Enhanced cache configuration with optimization strategies
const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 5 * 60 * 1000, // 5 minutes
      gcTime: 30 * 60 * 1000, // 30 minutes
      retry: (failureCount, error) => {
        const networkOptimizer = new NetworkOptimizer()
        const retryConfig = networkOptimizer.getRetryConfig()
        return failureCount < retryConfig.attempts
      },
      retryDelay: (attemptIndex) => {
        const networkOptimizer = new NetworkOptimizer()
        const retryConfig = networkOptimizer.getRetryConfig()
        return Math.min(1000 * 2 ** attemptIndex, retryConfig.delay)
      },
      refetchOnWindowFocus: false,
      refetchOnReconnect: 'always',
      networkMode: 'offlineFirst'
    },
    mutations: {
      retry: 2,
      networkMode: 'offlineFirst'
    }
  }
})

// Initialize optimizers
const cacheOptimizer = new CacheOptimizer(queryClient)
const networkOptimizer = new NetworkOptimizer()

// Enhanced persistence with compression and analytics
const setupQueryClientPersistence = () => {
  const CACHE_KEY = 'wildlife-app-cache'
  const CACHE_VERSION = '2.0'
  
  // Restore cache from localStorage with decompression
  const restoreCache = () => {
    try {
      const stored = localStorage.getItem(CACHE_KEY)
      if (stored) {
        const { version, data, timestamp } = JSON.parse(stored)
        
        // Check cache version and age
        const isValidVersion = version === CACHE_VERSION
        const isNotExpired = Date.now() - timestamp < 24 * 60 * 60 * 1000 // 24 hours
        
        if (isValidVersion && isNotExpired && data) {
          // Decompress and restore cache
          const decompressedData = JSON.parse(atob(data))
          queryClient.setQueryData(['cached-state'], decompressedData)
          
          // Update cache optimizer metrics
          cacheOptimizer.updateMetrics({
            hitRate: decompressedData.hitRate || 85,
            memoryUsage: decompressedData.memoryUsage || 45
          })
        }
      }
    } catch (error) {
      console.warn('Failed to restore cache:', error)
    }
  }
  
  // Save cache to localStorage with compression
  const saveCache = () => {
    try {
      const cache = queryClient.getQueryCache()
      const queries = cache.getAll()
      
      const cacheData = {
        queries: queries.map(query => ({
          queryKey: query.queryKey,
          data: query.state.data,
          dataUpdatedAt: query.state.dataUpdatedAt,
          status: query.state.status
        })).slice(0, 50), // Limit cache size
        timestamp: Date.now(),
        hitRate: cacheOptimizer.getMetrics().hitRate,
        memoryUsage: cacheOptimizer.getMetrics().memoryUsage
      }
      
      // Compress cache data
      const compressedData = btoa(JSON.stringify(cacheData))
      
      localStorage.setItem(CACHE_KEY, JSON.stringify({
        version: CACHE_VERSION,
        data: compressedData,
        timestamp: Date.now()
      }))
    } catch (error) {
      console.warn('Failed to save cache:', error)
    }
  }
  
  // Restore cache on initialization
  restoreCache()
  
  // Save cache periodically and on page unload
  setInterval(saveCache, 2 * 60 * 1000) // Every 2 minutes
  window.addEventListener('beforeunload', saveCache)
  
  // Cleanup old cache entries
  const cleanupCache = () => {
    const cache = queryClient.getQueryCache()
    const queries = cache.getAll()
    const now = Date.now()
    const maxAge = 60 * 60 * 1000 // 1 hour
    
    queries.forEach(query => {
      if (query.state.dataUpdatedAt && now - query.state.dataUpdatedAt > maxAge) {
        cache.remove(query)
      }
    })
  }
  
  setInterval(cleanupCache, 10 * 60 * 1000) // Every 10 minutes
}

export { 
  queryClient, 
  setupQueryClientPersistence, 
  cacheOptimizer, 
  networkOptimizer 
}
