import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Slider } from './ui/slider';
import { Badge } from './ui/badge';
import { Camera, Aperture, Timer, Zap } from 'lucide-react';

export default function CameraSettingsSimulator() {
  const [aperture, setAperture] = useState([2.8]);
  const [shutterSpeed, setShutterSpeed] = useState([125]);
  const [iso, setIso] = useState([400]);
  const [exposure, setExposure] = useState(0);

  const apertureValues = [1.4, 2, 2.8, 4, 5.6, 8, 11, 16];
  const shutterSpeeds = [30, 60, 125, 250, 500, 1000, 2000, 4000];
  const isoValues = [100, 200, 400, 800, 1600, 3200, 6400, 12800];

  useEffect(() => {
    // Calculate exposure value (simplified)
    const ev = Math.log2(aperture[0] * aperture[0] / (shutterSpeed[0] / 1000)) - Math.log2(iso[0] / 100);
    setExposure(ev);
  }, [aperture, shutterSpeed, iso]);

  const getExposureStatus = () => {
    if (exposure < -1) return { status: 'Underexposed', color: 'bg-blue-500', advice: 'Increase ISO or slow shutter speed' };
    if (exposure > 1) return { status: 'Overexposed', color: 'bg-red-500', advice: 'Decrease ISO or faster shutter speed' };
    return { status: 'Well Exposed', color: 'bg-green-500', advice: 'Perfect exposure for wildlife!' };
  };

  const exposureInfo = getExposureStatus();

  return (
    <Card className="w-full max-w-4xl mx-auto">
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Camera className="h-6 w-6" />
          Interactive Camera Settings Simulator
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-6">
        <div className="grid md:grid-cols-3 gap-6">
          <div className="space-y-3">
            <div className="flex items-center gap-2">
              <Aperture className="h-4 w-4" />
              <span className="font-medium">Aperture</span>
              <Badge variant="outline">f/{apertureValues[aperture[0]]}</Badge>
            </div>
            <Slider
              value={aperture}
              onValueChange={setAperture}
              max={7}
              min={0}
              step={1}
              className="w-full"
            />
            <p className="text-sm text-muted-foreground">
              Controls depth of field. Lower f-numbers = shallower depth.
            </p>
          </div>

          <div className="space-y-3">
            <div className="flex items-center gap-2">
              <Timer className="h-4 w-4" />
              <span className="font-medium">Shutter Speed</span>
              <Badge variant="outline">1/{shutterSpeeds[shutterSpeed[0]]}</Badge>
            </div>
            <Slider
              value={shutterSpeed}
              onValueChange={setShutterSpeed}
              max={7}
              min={0}
              step={1}
              className="w-full"
            />
            <p className="text-sm text-muted-foreground">
              Controls motion blur. Faster speeds freeze movement.
            </p>
          </div>

          <div className="space-y-3">
            <div className="flex items-center gap-2">
              <Zap className="h-4 w-4" />
              <span className="font-medium">ISO</span>
              <Badge variant="outline">{isoValues[iso[0]]}</Badge>
            </div>
            <Slider
              value={iso}
              onValueChange={setIso}
              max={7}
              min={0}
              step={1}
              className="w-full"
            />
            <p className="text-sm text-muted-foreground">
              Controls sensor sensitivity. Higher ISO = more noise.
            </p>
          </div>
        </div>

        <div className="bg-muted p-4 rounded-lg">
          <div className="flex items-center justify-between mb-2">
            <span className="font-medium">Exposure Result:</span>
            <Badge className={`${exposureInfo.color} text-white`}>
              {exposureInfo.status}
            </Badge>
          </div>
          <p className="text-sm text-muted-foreground">{exposureInfo.advice}</p>
        </div>
      </CardContent>
    </Card>
  );
}