// Network-aware optimization strategies
interface NetworkInfo {
  effectiveType: string
  downlink: number
  rtt: number
  saveData: boolean
}

interface OptimizationConfig {
  imageQuality: 'low' | 'medium' | 'high'
  prefetchCount: number
  cacheStrategy: 'aggressive' | 'moderate' | 'conservative'
  retryAttempts: number
}

class NetworkOptimizer {
  private networkInfo: NetworkInfo | null = null
  private config: OptimizationConfig = {
    imageQuality: 'medium',
    prefetchCount: 5,
    cacheStrategy: 'moderate',
    retryAttempts: 2
  }

  constructor() {
    this.detectNetworkCapabilities()
    this.setupNetworkChangeListener()
  }

  private detectNetworkCapabilities() {
    const connection = (navigator as unknown as { connection?: { effectiveType?: string; downlink?: number; rtt?: number; saveData?: boolean } }).connection
    if (connection) {
      this.networkInfo = {
        effectiveType: connection.effectiveType,
        downlink: connection.downlink,
        rtt: connection.rtt,
        saveData: connection.saveData
      }
      this.optimizeForNetwork()
    }
  }

  private setupNetworkChangeListener() {
    const connection = (navigator as unknown as { connection?: { addEventListener?: (type: string, listener: EventListenerOrEventListenerObject) => void } }).connection
    if (connection && typeof connection.addEventListener === 'function') {
      connection.addEventListener('change', () => {
        this.detectNetworkCapabilities()
      })
    }
  }

  private optimizeForNetwork() {
    if (!this.networkInfo) return

    const { effectiveType, downlink, saveData } = this.networkInfo

    if (saveData) {
      this.config = {
        imageQuality: 'low',
        prefetchCount: 2,
        cacheStrategy: 'conservative',
        retryAttempts: 1
      }
    } else if (effectiveType === 'slow-2g' || downlink < 0.5) {
      this.config = {
        imageQuality: 'low',
        prefetchCount: 3,
        cacheStrategy: 'aggressive',
        retryAttempts: 1
      }
    } else if (effectiveType === '2g' || downlink < 1.5) {
      this.config = {
        imageQuality: 'medium',
        prefetchCount: 5,
        cacheStrategy: 'moderate',
        retryAttempts: 2
      }
    } else if (effectiveType === '3g' || downlink < 5) {
      this.config = {
        imageQuality: 'medium',
        prefetchCount: 8,
        cacheStrategy: 'moderate',
        retryAttempts: 2
      }
    } else {
      this.config = {
        imageQuality: 'high',
        prefetchCount: 12,
        cacheStrategy: 'moderate',
        retryAttempts: 3
      }
    }
  }

  getOptimizedImageUrl(baseUrl: string): string {
    const quality = this.config.imageQuality
    const qualityMap = {
      low: 'q_30,f_auto',
      medium: 'q_70,f_auto',
      high: 'q_90,f_auto'
    }
    
    return `${baseUrl}?${qualityMap[quality]}`
  }

  shouldPrefetch(): boolean {
    if (!this.networkInfo) return true
    
    const { effectiveType, saveData } = this.networkInfo
    return !saveData && effectiveType !== 'slow-2g'
  }

  getPrefetchCount(): number {
    return this.config.prefetchCount
  }

  getRetryConfig() {
    return {
      attempts: this.config.retryAttempts,
      delay: this.networkInfo?.rtt ? Math.max(1000, this.networkInfo.rtt * 2) : 1000
    }
  }

  getCacheStrategy(): OptimizationConfig['cacheStrategy'] {
    return this.config.cacheStrategy
  }

  getNetworkStatus(): string {
    if (!this.networkInfo) return 'unknown'
    
    const { effectiveType, downlink } = this.networkInfo
    if (effectiveType === '4g' && downlink > 10) return 'excellent'
    if (effectiveType === '4g' || downlink > 5) return 'good'
    if (effectiveType === '3g' || downlink > 1.5) return 'fair'
    return 'poor'
  }

  getOptimizationSuggestions(): string[] {
    const suggestions: string[] = []
    
    if (!this.networkInfo) return suggestions

    const { effectiveType, saveData, downlink } = this.networkInfo

    if (saveData) {
      suggestions.push('Data saver mode detected - using optimized images')
    }

    if (effectiveType === 'slow-2g' || downlink < 0.5) {
      suggestions.push('Slow connection detected - reducing image quality')
      suggestions.push('Enabling aggressive caching')
    }

    if (downlink > 10) {
      suggestions.push('Fast connection - enabling high quality images')
      suggestions.push('Increasing prefetch count for better UX')
    }

    return suggestions
  }
}

export { NetworkOptimizer, type NetworkInfo, type OptimizationConfig }