import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Camera, CheckCircle, XCircle, RotateCcw } from 'lucide-react';

interface Question {
  id: number;
  question: string;
  options: string[];
  correct: number;
  explanation: string;
}

const questions: Question[] = [
  {
    id: 1,
    question: "What is the best aperture for isolating a bird from its background?",
    options: ["f/16", "f/8", "f/2.8", "f/11"],
    correct: 2,
    explanation: "f/2.8 creates a shallow depth of field, blurring the background and making the bird stand out."
  },
  {
    id: 2,
    question: "When photographing fast-moving wildlife, what shutter speed is recommended?",
    options: ["1/60s", "1/125s", "1/500s", "1/30s"],
    correct: 2,
    explanation: "1/500s or faster freezes motion, preventing blur in fast-moving subjects."
  },
  {
    id: 3,
    question: "What is the ethical minimum distance from nesting birds?",
    options: ["5 feet", "10 feet", "25 feet", "100 feet"],
    correct: 2,
    explanation: "25 feet minimum helps avoid disturbing nesting behavior and protects both wildlife and photographer."
  }
];

export default function WildlifePhotoQuiz() {
  const [currentQuestion, setCurrentQuestion] = useState(0);
  const [selectedAnswer, setSelectedAnswer] = useState<number | null>(null);
  const [showResult, setShowResult] = useState(false);
  const [score, setScore] = useState(0);
  const [answers, setAnswers] = useState<number[]>([]);

  const handleAnswer = (answerIndex: number) => {
    setSelectedAnswer(answerIndex);
    setShowResult(true);
    
    const newAnswers = [...answers];
    newAnswers[currentQuestion] = answerIndex;
    setAnswers(newAnswers);
    
    if (answerIndex === questions[currentQuestion].correct) {
      setScore(score + 1);
    }
  };

  const nextQuestion = () => {
    if (currentQuestion < questions.length - 1) {
      setCurrentQuestion(currentQuestion + 1);
      setSelectedAnswer(null);
      setShowResult(false);
    }
  };

  const resetQuiz = () => {
    setCurrentQuestion(0);
    setSelectedAnswer(null);
    setShowResult(false);
    setScore(0);
    setAnswers([]);
  };

  const isQuizComplete = currentQuestion === questions.length - 1 && showResult;

  return (
    <Card className="w-full max-w-2xl mx-auto">
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Camera className="h-6 w-6" />
          Wildlife Photography Quiz
        </CardTitle>
        <div className="flex justify-between items-center">
          <Badge variant="outline">
            Question {currentQuestion + 1} of {questions.length}
          </Badge>
          <Badge variant="secondary">
            Score: {score}/{questions.length}
          </Badge>
        </div>
      </CardHeader>
      <CardContent className="space-y-6">
        <div className="w-full bg-gray-200 rounded-full h-2">
          <div 
            className="bg-green-600 h-2 rounded-full transition-all duration-300" 
            style={{ width: `${((currentQuestion + 1) / questions.length) * 100}%` }}
          />
        </div>

        <div className="space-y-4">
          <h3 className="text-lg font-semibold">
            {questions[currentQuestion].question}
          </h3>
          
          <div className="space-y-2">
            {questions[currentQuestion].options.map((option, index) => (
              <Button
                key={index}
                variant={
                  showResult 
                    ? index === questions[currentQuestion].correct 
                      ? "default" 
                      : index === selectedAnswer 
                        ? "destructive" 
                        : "outline"
                    : "outline"
                }
                className={`w-full text-left justify-start h-auto p-4 ${
                  showResult && index === questions[currentQuestion].correct 
                    ? "bg-green-600 hover:bg-green-700" 
                    : ""
                }`}
                onClick={() => !showResult && handleAnswer(index)}
                disabled={showResult}
              >
                <div className="flex items-center gap-2">
                  {showResult && index === questions[currentQuestion].correct && (
                    <CheckCircle className="h-4 w-4" />
                  )}
                  {showResult && index === selectedAnswer && index !== questions[currentQuestion].correct && (
                    <XCircle className="h-4 w-4" />
                  )}
                  {option}
                </div>
              </Button>
            ))}
          </div>

          {showResult && (
            <div className="p-4 bg-blue-50 rounded-lg border border-blue-200">
              <p className="text-sm text-blue-800">
                <strong>Explanation:</strong> {questions[currentQuestion].explanation}
              </p>
            </div>
          )}
        </div>

        <div className="flex justify-between">
          <Button 
            variant="outline" 
            onClick={resetQuiz}
            className="flex items-center gap-2"
          >
            <RotateCcw className="h-4 w-4" />
            Restart Quiz
          </Button>
          
          {showResult && !isQuizComplete && (
            <Button onClick={nextQuestion} className="bg-green-600 hover:bg-green-700">
              Next Question
            </Button>
          )}
          
          {isQuizComplete && (
            <div className="text-center">
              <Badge variant={score >= questions.length * 0.7 ? "default" : "secondary"} className="text-lg p-2">
                Final Score: {score}/{questions.length} ({Math.round((score/questions.length)*100)}%)
              </Badge>
            </div>
          )}
        </div>
      </CardContent>
    </Card>
  );
}