import ExifReader from 'exifreader';

export interface PhotoMetadata {
  camera?: string;
  lens?: string;
  aperture?: string;
  shutterSpeed?: string;
  iso?: string;
  focalLength?: string;
  timestamp?: string;
  gpsLatitude?: number;
  gpsLongitude?: number;
  width?: number;
  height?: number;
  fileSize?: number;
}

export async function extractMetadata(file: File): Promise<PhotoMetadata> {
  const metadata: PhotoMetadata = {
    fileSize: file.size,
    timestamp: file.lastModified ? new Date(file.lastModified).toISOString() : undefined,
  };

  try {
    // Get image dimensions
    const dimensions = await getImageDimensions(file);
    metadata.width = dimensions.width;
    metadata.height = dimensions.height;

    // Extract EXIF data using ExifReader
    const arrayBuffer = await file.arrayBuffer();
    const tags = ExifReader.load(arrayBuffer);

    // Extract camera information
    if (tags.Make?.description) {
      metadata.camera = `${tags.Make.description}${tags.Model?.description ? ` ${tags.Model.description}` : ''}`;
    }

    // Extract lens information
    if (tags.LensModel?.description) {
      metadata.lens = tags.LensModel.description;
    }

    // Extract exposure settings
    if (tags.FNumber?.description) {
      metadata.aperture = `f/${tags.FNumber.description}`;
    }

    if (tags.ExposureTime?.description) {
      metadata.shutterSpeed = `${tags.ExposureTime.description}s`;
    }

    if (tags.ISOSpeedRatings?.description) {
      metadata.iso = tags.ISOSpeedRatings.description;
    }

    if (tags.FocalLength?.description) {
      metadata.focalLength = `${tags.FocalLength.description}mm`;
    }

    // Extract GPS coordinates
    if (tags.GPSLatitude && tags.GPSLongitude) {
      metadata.gpsLatitude = parseFloat(tags.GPSLatitude.description || '0');
      metadata.gpsLongitude = parseFloat(tags.GPSLongitude.description || '0');
    }

    // Extract timestamp from EXIF if available
    if (tags.DateTime?.description) {
      metadata.timestamp = tags.DateTime.description;
    }

  } catch (error) {
    console.warn('Could not extract EXIF data:', error);
  }

  return metadata;
}

function getImageDimensions(file: File): Promise<{ width: number; height: number }> {
  return new Promise((resolve) => {
    const img = new Image();
    img.onload = () => {
      resolve({ width: img.naturalWidth, height: img.naturalHeight });
      URL.revokeObjectURL(img.src);
    };
    img.onerror = () => {
      resolve({ width: 0, height: 0 });
      URL.revokeObjectURL(img.src);
    };
    img.src = URL.createObjectURL(file);
  });
}